"""Request handling. See api/API.md."""
import json

from . import binding
from .store import Store
from .validate import is_valid_url

NOT_FOUND = (404, {"error": "not found"})
BAD_METHOD = (405, {"error": "method not allowed"})


class App:
    def __init__(self, store=None, codec=None):
        self.store = store if store is not None else Store()
        self.codec = codec if codec is not None else binding

    def handle(self, method: str, path: str, body: bytes = b"") -> tuple[int, dict]:
        path = path.split("?", 1)[0]
        if path == "/health":
            return (200, {"ok": True}) if method == "GET" else BAD_METHOD
        if path == "/stats":
            return (200, {"count": len(self.store)}) if method == "GET" else BAD_METHOD
        if path == "/shorten":
            return self._shorten(body) if method == "POST" else BAD_METHOD
        if path.startswith("/lookup/"):
            return self._lookup(path[len("/lookup/"):]) if method == "GET" else BAD_METHOD
        return NOT_FOUND

    def _shorten(self, body: bytes) -> tuple[int, dict]:
        try:
            data = json.loads(body or b"")
        except ValueError:
            return 400, {"error": "invalid json"}
        if not isinstance(data, dict):
            return 400, {"error": "invalid json"}
        url = data.get("url")
        if not is_valid_url(url):
            return 400, {"error": "invalid url"}
        id = self.store.add(url)
        return 201, {"code": self.codec.encode(id), "url": url}

    def _lookup(self, code: str) -> tuple[int, dict]:
        try:
            id = self.codec.decode(code)
        except ValueError:
            return NOT_FOUND
        url = self.store.get(id)
        if url is None:
            return NOT_FOUND
        return 200, {"code": code, "url": url, "hits": self.store.hit(id)}
